function prevFY(fy){const y=+fy.slice(0,4)-1;return y+'-'+String(y+1).slice(2)}
function page(id,body){return crumb([R1.type,ttl(id)])+hdrBox(ttl(id))+body+`<div class="rbar"><button class="btn" onclick="open1(R1.type)">BACK</button></div>`}
function sTax(){const v=+($('s_val')||{}).value||0,r=+($('s_rate')||{value:0}).value,pos=($('s_pos')||{}).value;if(!$('s_rate')){return}const t=v*r/100,intra=pos===U.state;$('s_igst').value=intra?0:n2(t);$('s_cgst').value=intra?n2(t/2):0;$('s_sgst').value=intra?n2(t/2):0}
function saveS(id,tab,idx){const x=gx(),r={tab};['pos','rate','hsn','desc','uqc','qty','eg','sg','rg2','no','date','val'].forEach(k=>{const e=$('s_'+k);if(e)r[k]=['rate','qty','val'].includes(k)?+e.value||0:e.value.trim()});H.forEach(h=>r[h]=+$('s_'+h).value||0);const e=[];
if(r.hsn!==undefined&&!/^\d{4,8}$/.test(r.hsn))e.push('HSN must be 4, 6 or 8 digits');if(r.qty!==undefined&&r.uqc!=='NA'&&!(r.qty>0))e.push('Total Quantity is required (use UQC NA for services)');
if(r.eg!==undefined&&!validGSTIN(r.eg))e.push('Enter a valid GSTIN of e-commerce operator');if(r.sg!==undefined&&!validGSTIN(r.sg))e.push('Enter a valid Supplier GSTIN/UIN');if(!(r.val>0)&&id!=='eco')e.push('Value must be greater than 0');
if(e.length){$('s_e').innerHTML=e.join('<br>');return}if(idx>=0)x[id][idx]=r;else x[id].push(r);px(x);S1.form='new';S1.msg='Request accepted successfully.';openT(id)}
function delS(id,i){if(!confirm('Are you sure you want to delete the record?'))return;const x=gx();x[id].splice(i,1);px(x);openT(id)}
function saveNil(){const x=gx();['inter_reg','intra_reg','inter_unreg','intra_unreg'].forEach(k=>{x.nil[k]={};['nil','exm','ngs'].forEach(c=>x.nil[k][c]=+$(`n_${k}_${c}`).value||0)});px(x);S1.msg='Request accepted successfully.';alert('Request accepted successfully.');open1(R1.type)}
function saveDoc(){const x=gx();x.doc=[];for(let i=0;i<12;i++){const r={nat:i+1,from:$(`dc_${i}_from`).value.trim(),to:$(`dc_${i}_to`).value.trim(),tot:+$(`dc_${i}_tot`).value||0,can:+$(`dc_${i}_can`).value||0};if(r.can>r.tot)return alert('Cancelled cannot be more than Total Number (row '+(i+1)+')');if(r.tot)x.doc.push(r)}px(x);alert('Request accepted successfully.');open1(R1.type)}
function autoDoc(){const l=docsFor(R1.type,R1.p),inv=l.filter(d=>!['7','9B','9BU','9A','9C'].includes(d.tbl)).map(d=>d.no).sort(),cn=l.filter(d=>(d.tbl==='9B'||d.tbl==='9BU')&&d.ntype==='C').map(d=>d.no).sort(),dn=l.filter(d=>(d.tbl==='9B'||d.tbl==='9BU')&&d.ntype==='D').map(d=>d.no).sort();
const put1=(i,a)=>{if(!a.length)return;$(`dc_${i}_from`).value=a[0];$(`dc_${i}_to`).value=a[a.length-1];$(`dc_${i}_tot`).value=a.length;$(`dc_${i}_can`).value=0;$(`dc_${i}_net`).textContent=a.length};put1(0,inv);put1(3,dn);put1(4,cn)}
function autoHSN(){const x=gx(),m={};docsFor(R1.type,R1.p).forEach(d=>{if(d.orig||d.tbl==='9A'||d.tbl==='9C')return;const tab=['4A','9B'].includes(d.tbl)?'B2B':'B2C';const k=tab+'|'+d.hsn+'|'+d.rate;const sg=(d.tbl==='9B'||d.tbl==='9BU')&&d.ntype==='C'?-1:1;
m[k]=m[k]||{tab,hsn:d.hsn,desc:'',uqc:String(d.hsn).startsWith('99')?'NA':'NOS-NUMBERS',qty:0,rate:d.rate,val:0,...zero()};m[k].qty+=String(d.hsn).startsWith('99')?0:sg;m[k].val=n2(m[k].val+sg*d.val);H.forEach(h=>m[k][h]=n2(m[k][h]+sg*(d[h]||0)))});
x.hsn=Object.values(m);px(x);S1.msg='HSN records filled from your invoices/notes (practice helper). Check quantity and UQC.';openT('hsn')}
