function gen1(){const x=gx(),l=docsFor(R1.type,R1.p),b2b=l.some(d=>['4A','9B','9A','9C'].includes(d.tbl)),b2c=l.some(d=>['5','6A','7','9BU'].includes(d.tbl))||Object.values(x.nil).some(r=>r.nil||r.exm||r.ngs),hB=x.hsn.filter(h=>h.tab==='B2B'),hC=x.hsn.filter(h=>h.tab==='B2C');const E=[],W=[];
if(R1.type==='GSTR-1'){if(!anyData(x)&&x.hsn.length)E.push('Table 12 has data but there is no data in other tables of GSTR-1. Please add the supplies before generating summary.');
if(b2b&&!hB.length)E.push('Please enter HSN-wise details in B2B Supplies tab of Table 12 as you have reported B2B supplies.');if(anyData(x)&&!x.doc.length)E.push('Table 13 (Documents Issued) is mandatory. Please enter details of documents issued.');
if(b2c&&!hC.length)W.push('No data entered in B2C Supplies tab of Table 12 although B2C supplies are reported.');
const tv=list=>n2(list.reduce((a,h)=>a+h.val,0));const rb=n2(sumDocs(l.filter(d=>['4A','9B'].includes(d.tbl))).val);if(hB.length&&Math.abs(tv(hB)-rb)>1)W.push(`Taxable value in Table 12 (B2B Supplies) ₹${f(tv(hB))} does not match the B2B tables total ₹${f(rb)}.`)}
if(E.length){mdl(`<h3>Error</h3>${E.map(e=>`<p class="err">${e}</p>`).join('')}<button class="btn s" onclick="closeM()">OK</button>`,600);return}
const go=()=>{x.sum={at:new Date().toLocaleString('en-IN'),sig:sig()};px(x);closeM();open1(R1.type);document.querySelector('#main').insertAdjacentHTML('afterbegin','<div class="msg">Request for summary generation is accepted. Summary generated; status changed to Ready to File.</div>')};
if(W.length){mdl(`<h3>Warning</h3>${W.map(w=>`<p>${w}</p>`).join('')}<p>Do you want to continue with summary generation?</p><button class="btn" onclick="closeM()">CANCEL</button> <button class="btn s" onclick="_go()">PROCEED</button>`,600);window._go=go;return}go()}
function sumRows(){const x=gx(),l=docsFor(R1.type,R1.p);const rows=[];const tb=(id,lbl)=>{const t=tblOf(id),s=sumDocs(recs(t));rows.push({lbl,n:recs(t).length,v:s.val,...pick(s)})};
const ids=R1.type==='IFF'?['b2b','cdnr','a9b2b','a9cdnr']:['b2b','b2cl','exp','b2cs','cdnr','cdnur','a9b2b','a9cdnr'];ids.forEach(id=>tb(id,ttl(id)));
if(R1.type==='GSTR-1'){const nv=Object.values(x.nil).reduce((a,r)=>a+(r.nil||0)+(r.exm||0)+(r.ngs||0),0);rows.splice(4,0,{lbl:ttl('nil'),n:Object.values(x.nil).filter(r=>r.nil||r.exm||r.ngs).length,v:nv,...zero()});
['at','atadj','eco','s95'].forEach(k=>{const s={val:0,...zero()};x[k].forEach(r=>{s.val+=r.val;H.forEach(h=>s[h]+=r[h])});rows.push({lbl:ttl(k),n:x[k].length,v:s.val,...pick(s)})});
['B2B','B2C'].forEach(tb=>{const s={val:0,...zero()},L=x.hsn.filter(h=>h.tab===tb);L.forEach(r=>{s.val+=r.val;H.forEach(h=>s[h]+=r[h])});rows.push({lbl:'12 - HSN-wise summary ('+tb+' Supplies)',n:L.length,v:s.val,...pick(s)})});
rows.push({lbl:ttl('doc'),n:x.doc.reduce((a,r)=>a+r.tot-r.can,0),v:0,...zero(),doc:1})}
const tot={v:0,...zero()};const liabT=sumDocs(l.filter(d=>d.rc!=='Yes'));return {rows,liab:liabT}}
function sumHTML(){const {rows,liab}=sumRows(),l=docsFor(R1.type,R1.p);const by={};l.filter(d=>['4A','9B'].includes(d.tbl)).forEach(d=>{const sg=d.tbl==='9B'&&d.ntype==='C'?-1:1;by[d.rg]=by[d.rg]||{n:0,v:0,...zero()};by[d.rg].n++;by[d.rg].v+=sg*d.val;H.forEach(h=>by[d.rg][h]+=sg*d[h])});
return `<table class="sumt"><tr><th>Description</th><th>No. of records</th><th>Value (₹)</th>${H.map(h=>`<th>${HN[h]} (₹)</th>`).join('')}</tr>${rows.map(r=>`<tr><td>${r.lbl}</td><td>${r.n}</td><td>${r.doc?'-':f(r.v)}</td>${H.map(h=>`<td>${r.doc?'-':f(r[h])}</td>`).join('')}</tr>`).join('')}
<tr class="tot"><td>Total Liability (Outward supplies other than Reverse charge)</td><td></td><td>${f(liab.val)}</td>${H.map(h=>`<td>${f(liab[h])}</td>`).join('')}</tr></table>
<h4>Recipient wise summary (Tables 4A, 4B, 6B, 6C &amp; 9B)</h4><table><tr><th>Recipient GSTIN/UIN</th><th>Recipient Name</th><th>No. of records</th><th>Taxable value (₹)</th>${H.map(h=>`<th>${HN[h]}</th>`).join('')}</tr>${Object.entries(by).map(([g,s])=>`<tr><td>${g}</td><td>${esc((userBy(g)||{}).legal||'')}</td><td>${s.n}</td><td>${f(s.v)}</td>${H.map(h=>`<td>${f(s[h])}</td>`).join('')}</tr>`).join('')||'<tr><td colspan=8>No B2B records</td></tr>'}</table>`}
