function isNil3(d){return H.every(h=>!liab3b(d)[h]&&!d.t31d[h])&&!d.t31a.val}
function sysInt(d){const days=lateFee(P3,false).days;const L=liab3b(d),bal=credBal(),net=netITC(d),C={};H.forEach(h=>C[h]=Math.max(0,bal[h]+net[h]));const {rem}=utilise(L,C);const o={};H.forEach(h=>o[h]=+((rem[h]+(+d.t311i[h]||0)+(+d.t31d[h]||0))*0.18*days/365).toFixed(0));return o}
function reInt(){const {d}=g3(),si=sysInt(d);H.forEach(h=>{const e=$('t51_int_'+h);e.dataset.sys=si[h];if(e.disabled)return;e.value=si[h];chk(e)});alert('Interest re-computed on the basis of current values.')}
function conf3b(id){const {d}=g3(),v=k=>+($(k)||{value:0}).value||0;
if(id==='31'||id==='311'){(id==='31'?['t31a','t31b','t31c','t31d','t31e']:['t311i','t311ii']).forEach(k=>{['val',...H].forEach(c=>{if($(k+'_'+c))d[k][c]=v(k+'_'+c)})})}
if(id==='32'){for(const r of _t32){if(r.igst>r.val*0.4+0.01)return alert('Integrated tax cannot be more than 40% of taxable value');}d.t32r=_t32}
if(id==='4'){for(const k of ['a1','a2','a3','a4','a5','b1','b2','d1','d2'])H.forEach(c=>{if($('t4_'+k+'_'+c))d.t4[k][c]=v('t4_'+k+'_'+c)});if(H.some(h=>['a1','a2','a3','a4','a5'].some(k=>d.t4[k][h]<0)))return alert('ITC values in 4(A) cannot be negative')}
if(id==='5')d.t5={inter:v('t5_inter'),intra:v('t5_intra'),ngInter:v('t5_ngInter'),ngIntra:v('t5_ngIntra')};
if(id==='51'){d.t51.decl=$('t51decl').checked;H.forEach(c=>d.t51.int[c]=d.t51.decl?v('t51_int_'+c):0);const si=sysInt(d);if(d.t51.decl&&H.some(h=>d.t51.int[h]<si[h]*0.5))return alert('Interest entered is lower than the permissible limit of the system computed interest. CONFIRM is not allowed.')}
s3(d);closeM();land3b()}
function sysPdf(){const sy=sys3b(P3);const d={...sy,t31c:sy.t31c,t5:{inter:0,intra:0,ngInter:0,ngIntra:0},t32r:sy.t32,t51:{int:zero(),fee:zero()}};sync3b(d);paper3b(d,'System generated GSTR-3B (computed from GSTR-1/IFF and GSTR-2B)')}
