function paper3b(d,ttl){const n=netITC(d),rw=(l,o,cols)=>`<tr><td>${l}</td>${['val',...H].map(c=>`<td>${cols.includes(c)?f(o[c]):''}</td>`).join('')}</tr>`;const HC=['val',...H],r=filed('GSTR-3B',P3);
mdl(`<div class="paper"><div class="pp-h"><b>FORM GSTR-3B</b><br>${ttl}<br><small>Practice copy generated by GST Practice Portal · not an official document</small></div><table><tr><td>Year</td><td>${fyOf(P3)}</td><td>Period</td><td>${periodLabel(P3)}</td></tr><tr><td>1. GSTIN</td><td>${G}</td><td>2(a). Legal name</td><td>${esc(U.legal)}</td></tr><tr><td>ARN</td><td>${r?r.arn:'-'}</td><td>Date of ARN</td><td>${r?r.date:'-'}</td></tr></table>
<h4>3.1 Details of Outward supplies and inward supplies liable to reverse charge</h4><table><tr><th>Nature of Supplies</th><th>Total taxable value</th>${H.map(h=>`<th>${HN[h]}</th>`).join('')}</tr>${rw('(a) Outward taxable supplies (other than zero rated, nil rated and exempted)',d.t31a,HC)}${rw('(b) Outward taxable supplies (zero rated)',d.t31b,['val','igst','cess'])}${rw('(c) Other outward supplies (nil rated, exempted)',d.t31c,['val'])}${rw('(d) Inward supplies (liable to reverse charge)',d.t31d,HC)}${rw('(e) Non-GST outward supplies',d.t31e,['val'])}</table>
<h4>3.1.1 Supplies notified under section 9(5)</h4><table>${rw('(i) Taxable supplies on which ECO pays tax u/s 9(5)',d.t311i,HC)}${rw('(ii) Taxable supplies made by registered person through ECO',d.t311ii,['val'])}</table>
<h4>3.2 Inter-State supplies</h4><table><tr><th>Nature</th><th>Place of Supply</th><th>Taxable value</th><th>Integrated Tax</th></tr>${(d.t32r||[]).map(x=>`<tr><td>${x.nat}</td><td>${x.pos}</td><td>${f(x.val)}</td><td>${f(x.igst)}</td></tr>`).join('')||'<tr><td colspan=4>Nil</td></tr>'}</table>
<h4>4. Eligible ITC</h4><table><tr><th>Details</th>${H.map(h=>`<th>${HN[h]}</th>`).join('')}</tr>${[['a1','A(1) Import of goods'],['a2','A(2) Import of services'],['a3','A(3) Inward supplies liable to reverse charge'],['a4','A(4) Inward supplies from ISD'],['a5','A(5) All other ITC'],['b1','B(1) As per rules 38,42 & 43 and section 17(5)'],['b2','B(2) Others']].map(([k,l])=>`<tr><td>${l}</td>${TOT(d.t4[k])}</tr>`).join('')}<tr class="tot"><td>C. Net ITC available (A-B)</td>${TOT(n)}</tr>${[['d1','D(1) ITC reclaimed'],['d2','D(2) Ineligible ITC u/s 16(4) & PoS rules']].map(([k,l])=>`<tr><td>${l}</td>${TOT(d.t4[k])}</tr>`).join('')}</table>
<h4>5. Exempt, nil and Non-GST inward supplies</h4><table><tr><th>Nature</th><th>Inter-State</th><th>Intra-State</th></tr><tr><td>Composition, exempt and nil rated</td><td>${f(d.t5.inter)}</td><td>${f(d.t5.intra)}</td></tr><tr><td>Non GST supply</td><td>${f(d.t5.ngInter)}</td><td>${f(d.t5.ngIntra)}</td></tr></table>
<h4>5.1 Interest and Late fee</h4><table><tr><th></th>${H.map(h=>`<th>${HN[h]}</th>`).join('')}</tr><tr><td>Interest</td>${TOT(d.t51.int)}</tr><tr><td>Late fee</td>${TOT({...zero(),...lateFee(P3,isNil3(d))})}</tr></table>
${d.paid?`<h4>6.1 Payment of tax (paid in cash)</h4><table><tr><th></th>${H.map(h=>`<th>${HN[h]}</th>`).join('')}</tr><tr><td>Tax paid in cash</td>${TOT(d.paid.cash)}</tr></table>`:''}</div><div class="rbar"><button class="btn" onclick="closeM()">CLOSE</button><button class="btn s" onclick="window.print()">PRINT / SAVE AS PDF</button></div>`,1000)}
