function ptp(){const {d}=g3();mdl(`<h3>Warning</h3><p>Please ensure that the values entered in Form GSTR-3B are correct. Once you click on MAKE PAYMENT/POST CREDIT TO LEDGER, you will not be able to make any changes to the return. Do you want to proceed?</p><div class="rbar"><button class="btn" onclick="closeM()">CANCEL</button><button class="btn s" id="m_proc" onclick="closeM();payView()">PROCEED</button></div>`,600)}
function payCalc(ov){const {d}=g3(),L=liab3b(d),bal=credBal(),net=netITC(d),C={};H.forEach(h=>C[h]=n2(Math.max(0,bal[h]+net[h])));let {u,rem}=utilise(L,C);
if(ov){u=ov;rem={};H.forEach(h=>rem[h]=n2(L[h]-['igst','cgst','sgst','cess'].reduce((a,s)=>a+((u[s]||{})[h]||0),0)))}
const nil=isNil3(d),lf=lateFee(P3,nil),cash=cashBal(),need={},req={};const si=d.t51.decl?d.t51.int:zero();
H.forEach(h=>{const tax=Math.max(0,rem[h])+(+d.t311i[h]||0),rc=+d.t31d[h]||0,int=+si[h]||0,fee=lf[h]||0;need[h]={tax:n2(tax+rc),oth:n2(tax),rc:n2(rc),int,fee};req[h]={tax:Math.max(0,n2(tax+rc-cash[h+'_tax'])),interest:Math.max(0,int-cash[h+'_interest']),fee:Math.max(0,fee-cash[h+'_fee'])}});return {d,L,C,u,rem,need,req,cash,bal,net}}
let OV=null;
function payView(){if(!$('pv')){P3=P3||S.p;CURP=P3;land3b();if(!$('pv'))return}const x=payCalc(OV);const addl=n2(H.reduce((a,h)=>a+x.req[h].tax+x.req[h].interest+x.req[h].fee,0));const can={igst:['igst','cgst','sgst'],cgst:['cgst','igst'],sgst:['sgst','igst'],cess:['cess']};
const itcCell=(h,s)=>can[s].includes(h)?`<input type="number" class="itcu" id="u_${s}_${h}" value="${n2((x.u[s]||{})[h]||0)}" style="width:90px">`:'<span class="na">-</span>';
$('pv').innerHTML=`<div class="card" id="pay61"><h3>6.1 Payment of tax</h3>
<h4>Cash and ITC available as on date (ITC includes this period's net ITC)</h4><table><tr><th>Description</th><th>Cash Ledger: Tax (₹)</th><th>Interest (₹)</th><th>Late Fee (₹)</th><th>Credit Ledger balance incl. current ITC (₹)</th></tr>${H.map(h=>`<tr><td>${HN[h]}</td><td>${f(x.cash[h+'_tax'])}</td><td>${f(x.cash[h+'_interest'])}</td><td>${f(x.cash[h+'_fee'])}</td><td>${f(x.C[h])}</td></tr>`).join('')}</table>
<div class="scrollx"><table class="pay"><tr><th rowspan=2>Description</th><th rowspan=2>Tax payable (₹)</th><th rowspan=2>Adjustment of negative liability of previous tax period (₹)</th><th rowspan=2>Net Tax Payable (₹)</th><th colspan=4>Paid through ITC</th><th rowspan=2>Tax to be paid in cash (₹)</th><th rowspan=2>Interest payable (₹)</th><th rowspan=2>Interest to be paid in cash (₹)</th><th rowspan=2>Late Fee payable (₹)</th><th rowspan=2>Late Fee to be paid in cash (₹)</th><th rowspan=2>Utilizable Cash balance (₹)</th><th rowspan=2>Additional cash required (₹)</th></tr><tr><th>Integrated Tax</th><th>Central Tax</th><th>State/UT Tax</th><th>CESS</th></tr>
<tr class="sub"><td colspan=15><b>(A) Other than reverse charge</b></td></tr>${H.map(h=>`<tr><td>${HN[h]}</td><td>${f(x.L[h]+(+x.d.t311i[h]||0))}</td><td>0.00</td><td>${f(x.L[h]+(+x.d.t311i[h]||0))}</td>${['igst','cgst','sgst','cess'].map(s=>`<td>${itcCell(h,s)}</td>`).join('')}<td>${f(x.need[h].oth)}</td><td>${f(x.need[h].int)}</td><td>${f(x.need[h].int)}</td><td>${f(x.need[h].fee)}</td><td>${f(x.need[h].fee)}</td><td>${f(x.cash[h+'_tax']+x.cash[h+'_interest']+x.cash[h+'_fee'])}</td><td><b>${f(x.req[h].tax+x.req[h].interest+x.req[h].fee)}</b></td></tr>`).join('')}
<tr class="sub"><td colspan=15><b>(B) Reverse charge and supplies made u/s 9(5)</b> - paid in cash only</td></tr>${H.map(h=>`<tr><td>${HN[h]}</td><td>${f(x.need[h].rc)}</td><td>0.00</td><td>${f(x.need[h].rc)}</td><td colspan=4 class="na">-</td><td>${f(x.need[h].rc)}</td><td colspan=6></td></tr>`).join('')}</table></div>
<div class="note">"Paid through ITC" is auto-filled with the optimum utilisation as per law (IGST credit first towards IGST, then CGST/SGST; CGST credit towards CGST then IGST; SGST credit towards SGST then IGST; no CGST↔SGST cross-utilisation; cess only for cess). You may edit it and click RECALCULATE.</div><p class="err" id="u_e"></p>
${addl>0?`<p class="err">You do not have sufficient balance in Electronic Cash Ledger (additional ₹${f(addl)} required). Create a challan for the additional cash.</p>`:''}
<div class="rbar"><button class="btn" onclick="OV=null;land3b()">BACK</button><button class="btn" onclick="recalcU()">RECALCULATE</button>${addl>0?`<button class="btn s" id="b_chal" onclick="challanFor3b()">CREATE CHALLAN</button>`:''}<button class="btn s" id="b_offset" ${addl>0?'disabled':''} onclick="offset3b()">MAKE PAYMENT/POST CREDIT TO LEDGER</button></div></div>`;
$('bar3').style.display='none';$('pay61').scrollIntoView()}
function recalcU(){const x=payCalc(),u={igst:{},cgst:{},sgst:{},cess:{}};const can={igst:['igst','cgst','sgst'],cgst:['cgst','igst'],sgst:['sgst','igst'],cess:['cess']},E=[];
H.forEach(h=>Object.keys(can).forEach(s=>{if(can[s].includes(h))u[s][h]=+$('u_'+s+'_'+h).value||0}));Object.keys(u).forEach(s=>{const used=Object.values(u[s]).reduce((a,b)=>a+b,0);if(used>x.C[s]+0.01)E.push(`${HN[s]} credit used (₹${f(used)}) is more than available (₹${f(x.C[s])})`)});
H.forEach(h=>{const t=Object.keys(u).reduce((a,s)=>a+(u[s][h]||0),0);if(t>x.L[h]+0.01)E.push(`ITC used for ${HN[h]} is more than tax payable`)});if(u.igst&&x.C.igst>0&&(u.cgst.igst||0)+(u.sgst.igst||0)>0&&(u.igst.igst||0)<Math.min(x.C.igst,x.L.igst)-0.01)E.push('IGST credit must be used fully towards IGST before using CGST/SGST credit for IGST (Rule 88A)');
if(E.length){$('u_e').innerHTML=E.join('<br>');return}OV=u;payView()}
function challanFor3b(){const x=payCalc(OV),a={};H.forEach(h=>MIN.forEach(m=>a[h+'_'+m]=0));H.forEach(h=>{a[h+'_tax']=Math.ceil(x.req[h].tax);a[h+'_interest']=Math.ceil(x.req[h].interest);a[h+'_fee']=Math.ceil(x.req[h].fee)});sessionStorage.setItem('gpp_prefill',JSON.stringify({amt:a,back:P3}));show('Create Challan')}
function offset3b(){if(!confirm('Once you make payment / post credit to ledger you cannot change GSTR-3B. Click OK (YES) to proceed.'))return;const x=payCalc(OV),d=x.d,p=P3;
addCred('ITC of GSTR-3B '+p+' (Table 4C)',x.net);const usedFrom={};H.forEach(h=>usedFrom[h]=-Object.values(x.u[h]||{}).reduce((a,b)=>a+b,0));addCred('Utilised for GSTR-3B '+p,usedFrom);
const debit={},paidCash=zero();H.forEach(h=>{MIN.forEach(m=>debit[h+'_'+m]=0);debit[h+'_tax']=-x.need[h].tax;debit[h+'_interest']=-x.need[h].int;debit[h+'_fee']=-x.need[h].fee;paidCash[h]=x.need[h].tax});
if(H.some(h=>x.need[h].tax||x.need[h].int||x.need[h].fee))addCash('Debit for GSTR-3B '+p,debit);
const tot={};H.forEach(h=>tot[h]=n2(x.L[h]+(+d.t311i[h]||0)+(+d.t31d[h]||0)+x.need[h].int+x.need[h].fee));addLiab('Liability - GSTR-3B '+p+' (tax+interest+fee)',tot,'Dr');const cr={};H.forEach(h=>cr[h]=-tot[h]);addLiab('Paid / offset - GSTR-3B '+p,cr,'Cr');
d.offset=true;d.paid={cash:paidCash,need:x.need,itc:x.u};s3(d);OV=null;alert('Payment of tax has been successfully done. Liabilities offset and ledgers updated. Please proceed to file GSTR-3B.');land3b()}
function fileBox(d){return `<div class="card"><div class="msg">Payment of tax done. Tax paid in cash: ${H.map(h=>HN[h]+' ₹'+f(((d.paid||{}).cash||{})[h]||0)).join(', ')}.</div><button class="btn" onclick="brk3b()">TAX LIABILITY BREAKUP, AS APPLICABLE</button><br><br>
<label class="decl"><input type="checkbox" id="b3decl" onchange="$('b3dsc').disabled=$('b3evc').disabled=!this.checked"> I/We hereby solemnly affirm and declare that the information given herein above is true and correct to the best of my/our knowledge and belief and nothing has been concealed there from.</label>
<div class="row"><div><label>Authorised Signatory *</label><select id="b3as"><option value="">Select</option><option selected>${esc(U.as.name)}</option></select></div></div><br><button class="btn" onclick="draft3b()">PREVIEW DRAFT GSTR-3B</button> <button class="btn" id="b3dsc" disabled onclick="alert('Practice site: DSC signing is not simulated. Use FILE GSTR-3B WITH EVC.')">FILE GSTR-3B WITH DSC</button> <button class="btn s" id="b3evc" disabled onclick="file3b()">FILE GSTR-3B WITH EVC</button></div>`}
function brk3b(){const d=get('3b_'+P3);mdl(`<h3>Tax Liability Breakup, as applicable</h3><p>All tax paid in cash relates to the current tax period (${periodLabel(P3)}) in this practice. On the real portal you split it period-wise if part of the liability relates to earlier periods (used for interest).</p><table><tr><th>Tax period</th>${H.map(h=>`<th>${HN[h]}</th>`).join('')}</tr><tr><td>${periodLabel(P3)}</td>${TOT(d.paid.cash)}</tr></table><div class="rbar"><button class="btn s" onclick="closeM()">SAVE</button></div>`,800)}
function file3b(){if(!$('b3decl').checked)return alert('Please select the declaration checkbox');if(!$('b3as').value)return alert('Please select Authorised Signatory');if(!evc('GSTR-3B'))return;const d=get('3b_'+P3);const arn=addRet('GSTR-3B',P3,{cash:d.paid.cash});alert('GSTR-3B has been filed successfully. ARN: '+arn);land3b()}

function use2b(p){S.p=p;P3=p;CURP=p;const {d}=g3();d.t4.a5={...get('2b_'+p).itc};s3(d);alert('Table 4A(5) of GSTR-3B for '+p+' updated from GSTR-2B.');open3b()}
